```c
mrb_ary_shift_m(mrb_state *mrb, mrb_value self)
{
  struct RArray *a = mrb_ary_ptr(self);  // Get the array pointer
  mrb_int len = ARY_LEN(a);             // Get the length of the array
  mrb_int n;
  mrb_value val;

  // Check for arguments: expects an integer argument (or no argument)
  if (mrb_get_args(mrb, "|i", &n) == 0) {
    return mrb_ary_shift(mrb, self);  // If no argument, call standard shift (by 1)
  };
  ary_modify_check(mrb, a);            // Check if array is modifiable
  if (len == 0 || n == 0) return mrb_ary_new(mrb);  // Return empty array for n=0 or empty array
  if (n < 0) mrb_raise(mrb, E_ARGUMENT_ERROR, "negative array shift");  // Handle negative n
  if (n > len) n = len;                // Clamp n to len
  val = mrb_ary_new_from_values(mrb, n, ARY_PTR(a));  // Create new array with first n elements

  // Handle shared arrays
  if (ARY_SHARED_P(a)) {
    a->as.heap.ptr += n;
    a->as.heap.len -= n;
    return val;
  }

  // Convert to shared array if needed
  if (len > ARY_SHIFT_SHARED_MIN) {
    ary_make_shared(mrb, a);
    goto L_SHIFT;  // Skip to shared array handling
  }

  // Handle special case where n equals len
  else if (len == n) {
    ARY_SET_LEN(a, 0);  // Set array length to 0
  }
  else {
    // Non-shared array with n < len
    mrb_value *ptr = ARY_PTR(a);
    mrb_int size = len - n;

